307: function continueRun() {
308:   try {
309:     const raw = localStorage.getItem(SAVE_KEY);
310:     if (!raw) return;
311:     const data = JSON.parse(raw);
312:     if (!data || data.version !== 1) throw new Error('bad save');
313:     state.run = data;
314:     state.uid = Math.max(1, ...data.deck.map(c => parseInt(String(c.uid).replace('c', ''), 10) || 0)) + 1;
315:     if (!state.run.path) state.run.path = [...(state.run.visited || ['start'])];
316:     if (!state.run.balls) state.run.balls = { poke: 5, great: 1, ultra: 0, master: 0 };
317:     if (!state.run.relics) state.run.relics = [];
