371:     balls: { poke: 5, great: 1, ultra: 0, master: 0 },
372:     relics: [], current: 'start', visited: ['start'], path: ['start'],
373:     floor: 0, caught: 0, battles: 0, kills: 0, startedAt: Date.now()
374:   };
375:   state.run = run;
376:   for (const [id, count] of st.deck) {
377:     for (let i = 0; i < count; i++) run.deck.push(makeCard(id));
378:   }
379:   saveRun();
380:   showMap();
381:   toast(`The climb begins with ${st.name}.`, 'good');
