420: function availableNodes() {
421:   const run = state.run;
422:   if (!run) return [];
423:   const cur = NODE_BY_ID[run.current] || NODE_BY_ID.start;
424:   const next = MAP_NODES.filter(n => n.row === cur.row + 1 && Math.abs(n.col - cur.col) <= 1);
425:   return next.filter(n => !run.visited.includes(n.id));
426: }
427: function renderMap() {
428:   const run = state.run;
429:   if (!run) return;
430:   const nodesEl = $('#map-nodes');
431:   const svg = $('#map-lines');
432:   if (!nodesEl || !svg) return;
433:   const pos = (n) => ({ x: 18 + n.col * 32, y: 94 - n.row * 8.15 });
434:   const avail = new Set(availableNodes().map(n => n.id));
435:   const pathSet = new Set(run.path || run.visited);
436:   const cur = NODE_BY_ID[run.current] || NODE_BY_ID.start;
437:   const kicker = $('.map-heading .section-kicker');
438:   if (kicker) kicker.textContent = `Act I · The Verdant Spire · Floor ${Math.min(12, run.floor + 1)} / 12`;
439: 
440:   let svgHtml = '';
441:   for (const [a, b] of MAP_EDGES) {
442:     const na = NODE_BY_ID[a], nb = NODE_BY_ID[b];
443:     const pa = pos(na), pb = pos(nb);
444:     const d = `M ${pa.x} ${pa.y} C ${pa.x} ${pa.y - 3.2}, ${pb.x} ${pb.y + 3.2}, ${pb.x} ${pb.y}`;
445:     let cls = '';
446:     if (pathSet.has(a) && pathSet.has(b)) cls = 'route';
447:     else if (a === cur.id && avail.has(b)) cls = 'available';
448:     svgHtml += `<path class="${cls}" d="${d}"/>`;
449:   }
450:   svg.innerHTML = svgHtml;
