452:   nodesEl.innerHTML = MAP_NODES.map(n => {
453:     const p = pos(n);
454:     const meta = NODE_META[n.type] || NODE_META.wild;
455:     const visited = run.visited.includes(n.id);
456:     const isCurrent = run.current === n.id;
457:     const isAvailable = avail.has(n.id);
458:     const cls = ['map-node', `type-${n.type}`,
459:       visited ? 'visited' : '', isCurrent ? 'current' : '',
460:       isAvailable ? 'available' : (!visited && !isCurrent ? 'locked' : '')
461:     ].filter(Boolean).join(' ');
462:     const badge = isCurrent ? '<span class="node-badge">✦</span>' : '';
463:     return `<button class="${cls}" style="left:${p.x}%;top:${p.y}%" data-node="${n.id}"
464:       data-tip="<b>${meta.label}</b>${meta.desc}" aria-label="${meta.label}">
465:       ${icon(meta.icon)}${n.row > 0 ? `<span class="node-floor">${n.row + 1}</span>` : ''}${badge}
466:     </button>`;
467:   }).join('');
468: 
469:   $$('.map-node.available', nodesEl).forEach(btn => btn.addEventListener('click', () => {
470:     const n = NODE_BY_ID[btn.dataset.node];
471:     if (n) handleNodeClick(n);
472:   }));
473: 
474:   requestAnimationFrame(() => {
475:     const vp = $('#map-viewport');
