605: function chooseEnemySpecies(node) {
606:   const run = state.run;
607:   if (node.type === 'boss') return 'mewtwo';
608:   if (node.type === 'elite') {
609:     const pool = ELITE_POOL.filter(k => k !== run.lastElite);
610:     const key = pick(pool.length ? pool : ELITE_POOL);
611:     run.lastElite = key;
612:     return key;
613:   }
614:   if (node.type === 'grass' && Math.random() < .065) return 'mew';
615:   const tier = node.row <= 2 ? 1 : node.row <= 4 ? 2 : node.row <= 7 ? 3 : 4;
616:   const pool = (TIER_POOLS[tier] || TIER_POOLS[3]).filter(k => k !== run.lastWild);
617:   const key = pick(pool.length ? pool : TIER_POOLS[tier]);
618:   run.lastWild = key;
619:   return key;
620: }
