632: function startBattle(node) {
633:   const run = state.run;
634:   const key = chooseEnemySpecies(node);
635:   const sp = SPECIES[key];
636:   const isElite = node.type === 'elite';
637:   const isBoss = node.type === 'boss';
638:   let hp = Math.round(sp.baseHp * (1 + node.row * .012));
639:   if (node.type === 'grass') hp = Math.max(12, Math.round(hp * .55));
640:   if (isBoss) hp = sp.baseHp;
641:   if (isElite) hp = Math.round(sp.baseHp * 1.06);
642: 
643:   const enemy = {
644:     key, name: sp.name, types: sp.types, maxHp: hp, hp, block: 0,
645:     statuses: { poison: 0, burn: 0, weak: 0, vulnerable: 0 },
646:     strength: 0, moveIndex: 0, intent: null,
647:     level: 3 + node.row, isElite, isBoss, flavor: sp.flavor
648:   };
649:   const player = {
650:     block: 0, statuses: { poison: 0, burn: 0, weak: 0, vulnerable: 0 },
651:     energy: 3, maxEnergy: 3, strength: 0
652:   };
653:   if (hasRelic('choice_band')) player.strength += 2;
654:   if (hasRelic('bicycle')) player.energy += 1;
655: 
656:   const battle = {
657:     node, speciesKey: key, enemy, player,
658:     hand: [], drawPile: shuffle(run.deck.map(c => ({ ...c }))), discardPile: [], exhaustPile: [],
659:     turn: 1, busy: false, over: false, focusUsed: false, bossPhase: false,
660:     catchBonus: node.type === 'grass' ? 12 : 0,
661:     lastLog: null, rewards: null
662:   };
663:   state.battle = battle;
664:   state.node = node;
665:   run.battles++;
666:   enemy.intent = getEnemyIntent(battle);
667:   setScreen('battle');
668:   $('#screen-battle')?.classList.toggle('boss-fight', isBoss);
669:   drawCards(5 + drawBonus());
670:   renderBattle();
671:   renderHand();
672:   const intro = isBoss ? 'The air turns to glass. Mewtwo descends.' :
673:     node.type === 'grass' ? `Something rustles in the tall grass... ${sp.name} appears, already weary.` :
674:     isElite ? `An elite ${sp.name} blocks the way!` :
675:     `A wild ${sp.name} appears!`;
676:   logBattle(intro);
677:   if (isBoss) toast('The Spire Heart awakens.', 'bad', 3200);
678:   if (node.type === 'grass') toast('It is already weakened — catch odds improved.', 'good');
679:   if (key === 'mew') { toast('A rare shimmer... Mew!', 'good', 3600); fxBanner('A RARE SHIMMER'); }
680: }
