742: function statusPills(statuses, strength = 0) {
743:   const list = [];
744:   const map = [
745:     ['poison', 'Poison', '☠'], ['burn', 'Burn', '♨'], ['weak', 'Weak', '↓'], ['vulnerable', 'Vuln', '◇']
746:   ];
747:   for (const [k, label, glyph] of map) {
748:     if (statuses?.[k] > 0) list.push(`<span class="status-pill ${k}">${glyph} ${label} <b>${statuses[k]}</b></span>`);
749:   }
750:   if (strength > 0) list.push(`<span class="status-pill strength">↑ Str <b>${strength}</b></span>`);
751:   return list.join('');
752: }
