754: function getEnemyIntent(b) {
755:   const sp = SPECIES[b.enemy.key];
756:   const idx = sp.pattern[b.enemy.moveIndex % sp.pattern.length];
757:   return { ...sp.moves[idx], index: b.enemy.moveIndex };
758: }
759: function calcEnemyHit(b, move) {
760:   let d = (move.dmg || 0) + b.enemy.strength;
761:   if (b.enemy.statuses.weak > 0) d = Math.floor(d * .75);
762:   if (b.player.statuses.vulnerable > 0) d = Math.floor(d * 1.5);
763:   return Math.max(0, d);
764: }
765: function renderIntent() {
766:   const b = state.battle;
767:   const move = b.enemy.intent;
768:   if (!move) return;
769:   const card = $('#enemy-intent');
770:   const iconEl = $('#intent-icon');
771:   const copy = $('#intent-value');
772:   let kind = move.kind || 'attack';
773:   let iconName = 'sword';
774:   let value = '';
775:   let label = 'Attack';
776:   if (kind === 'attack') {
777:     const per = calcEnemyHit(b, move);
778:     value = (move.hits || 1) > 1 ? `${per}×${move.hits}` : String(per);
779:     label = 'Attack';
780:   } else if (kind === 'defend') {
781:     iconName = 'shield'; value = String(move.block || 0); label = 'Defend';
782:   } else if (kind === 'buff') {
783:     iconName = 'arrowUp'; value = move.strength ? `+${move.strength}` : `+${move.block || 0}`; label = 'Power up';
784:   } else if (kind === 'debuff') {
785:     iconName = 'arrowDown'; value = String(Math.max(...Object.values(move.playerStatus || { weak: 1 }))); label = 'Hex';
786:   } else if (kind === 'heal') {
787:     iconName = 'heal'; value = `+${move.heal || 0}`; label = 'Recover';
788:   }
789:   card.className = 'intent-card ' + kind;
790:   iconEl.innerHTML = icon(iconName);
791:   copy.textContent = value;
792:   copy.closest('.intent-copy').querySelector('span').textContent = label;
793:   let nameEl = card.querySelector('.intent-name');
794:   if (!nameEl) {
795:     nameEl = document.createElement('span');
796:     nameEl.className = 'intent-name';
797:     card.querySelector('.intent-copy').appendChild(nameEl);
798:   }
799:   nameEl.textContent = move.name;
800:   card.dataset.tip = `<b>${move.name}</b>${intentTip(move)}`;
801: }
802: 
803: function intentTip(move) {
804:   const bits = [];
805:   if (move.dmg) bits.push(`Deals ${move.dmg}${move.hits > 1 ? `×${move.hits}` : ''} damage.`);
806:   if (move.block) bits.push(`Gains ${move.block} Block.`);
807:   if (move.strength) bits.push(`Gains ${move.strength} Strength.`);
808:   if (move.heal) bits.push(`Heals ${move.heal} HP.`);
809:   if (move.playerStatus) bits.push('Applies ' + Object.entries(move.playerStatus).map(([k, v]) => `${v} ${k}`).join(', ') + '.');
810:   if (move.stealGold) bits.push(`Steals ${move.stealGold} gold.`);
811:   if (move.selfDamage) bits.push(`Hurts itself for ${move.selfDamage}.`);
812:   return bits.join(' ');
813: }
