821:   if ((state.run.balls.master || 0) > 0) types.push('master');
822:   row.innerHTML = '';
823:   for (const t of types) {
824:     const count = state.run.balls[t] || 0;
825:     const chance = ballChance(t);
826:     const btn = document.createElement('button');
827:     btn.className = 'ball-btn';
