829:     btn.dataset.tip = `<b>${BALLS[t].name}</b>${count} remaining. Catch chance: ${chance}%. Throwing costs 1 Energy.`;
830:     btn.innerHTML = `<span class="ball-icon ${BALLS[t].cls}"></span>
831:       <span class="ball-btn-copy"><b>${BALLS[t].short}</b><span>${chance}%</span></span>
