838: function ballChance(type) {
839:   const b = state.battle;
840:   if (!b) return 0;
841:   if (type === 'master') return 100;
842:   const e = b.enemy;
843:   let c = 5 + (1 - e.hp / e.maxHp) * 72 + BALLS[type].bonus + b.catchBonus;
844:   if (hasRelic('lucky_egg')) c += 12;
845:   if (e.statuses.poison > 0) c += 4;
846:   if (e.statuses.burn > 0) c += 2;
847:   if (e.key === 'mew') c += 12;
848:   if (e.isBoss) c = e.hp / e.maxHp < .25 ? Math.min(c, 52) : Math.min(c, 6);
849:   else if (e.isElite) c = Math.min(c, 78);
850:   return Math.round(clamp(c, 2, 96));
851: }
852: function bestCatchChance() {
853:   if (!state.battle) return 0;
854:   let best = 0;
855:   for (const t of ['poke', 'great', 'ultra', 'master']) {
856:     if ((state.run.balls[t] || 0) > 0) best = Math.max(best, ballChance(t));
857:   }
858:   return best;
859: }
