896: function renderHand() {
897:   const b = state.battle;
898:   const handEl = $('#hand');
899:   if (!b || !handEl) return;
900:   const prevScroll = handEl.scrollLeft;
901:   handEl.innerHTML = '';
902:   if (!b.hand.length) {
903:     handEl.innerHTML = '<div style="font-size:10px;letter-spacing:.08em;color:var(--muted-2);padding:18px 0">No cards in hand — end your turn.</div>';
904:     updateHandFade();
905:     return;
906:   }
907:   for (const card of b.hand) {
908:     const stats = getStats(card.id, card.upgraded);
909:     const el = makeCardEl(card, {
910:       disabled: b.busy || b.over || stats.cost > b.player.energy,
911:       onClick: (c) => playCard(c.uid)
912:     });
913:     handEl.appendChild(el);
914:   }
915:   const mobile = innerWidth <= 760;
916:   if (mobile) {
917:     // On phones the hand is a horizontal scroller: never overlap cards.
918:     handEl.style.setProperty('--overlap', '0px');
919:     handEl.scrollLeft = prevScroll;
920:   } else {
921:     const count = b.hand.length;
922:     const cardW = innerHeight <= 680 ? 124 : 138;
923:     const gap = 6;
924:     const needed = count * cardW + Math.max(0, count - 1) * gap;
925:     const avail = Math.max(200, handEl.clientWidth - 10);
926:     const overlap = needed > avail ? -(needed - avail) / Math.max(1, count - 1) : 0;
927:     handEl.style.setProperty('--overlap', overlap.toFixed(1) + 'px');
928:   }
