1493:   sfx('card');
1494:   const chance = ballChance(type);
1495:   logBattle(`You throw a <b>${BALLS[type].name}</b>...`);
1496:   const anim = await animateBall(type, btn);
1497:   const success = type === 'master' || Math.random() * 100 < chance;
1498:   if (success) {
1499:     if (anim) {
1500:       const burst = document.createElement('div');
1501:       burst.className = 'catch-burst';
1502:       burst.style.left = anim.x + 'px'; burst.style.top = anim.y + 'px';
