1527: async function animateBall(type, btn) {
1528:   if (state.reduced) return null;
1529:   const layer = $('#fx-layer');
1530:   const target = $('#enemy-mon');
1531:   if (!layer || !target || !btn) return null;
1532:   const lr = layer.getBoundingClientRect();
1533:   const br = btn.getBoundingClientRect();
1534:   const tr = target.getBoundingClientRect();
1535:   const startX = br.left - lr.left + br.width / 2;
1536:   const startY = br.top - lr.top + br.height / 2;
1537:   const endX = tr.left - lr.left + tr.width / 2;
1538:   const endY = tr.top - lr.top + tr.height * .45;
1539:   const el = document.createElement('div');
1540:   el.className = 'ball-projectile ' + (BALLS[type].cls || '');
1541:   el.style.left = startX + 'px';
1542:   el.style.top = startY + 'px';
1543:   el.style.transform = 'translate(-50%,-50%)';
1544:   layer.appendChild(el);
1545:   const anim = el.animate([
1546:     { left: startX + 'px', top: startY + 'px', transform: 'translate(-50%,-50%) scale(.8) rotate(0deg)' },
1547:     { left: (startX + endX) / 2 + 'px', top: Math.min(startY, endY) - 70 + 'px', transform: 'translate(-50%,-50%) scale(1.1) rotate(220deg)', offset: .55 },
1548:     { left: endX + 'px', top: endY + 'px', transform: 'translate(-50%,-50%) scale(1) rotate(360deg)' }
1549:   ], { duration: 560, easing: 'cubic-bezier(.2,.8,.2,1)' });
1550:   await anim.finished.catch(() => {});
1551:   el.style.left = endX + 'px'; el.style.top = endY + 'px';
1552:   el.classList.add('ball-wobble');
1553:   await wait(950);
1554:   return { el, x: endX, y: endY };
1555: }
