.merchant-bubble{position:relative;margin-top:10px;padding:14px 15px;border-radius:12px;background:rgba(20,43,33,.82);border:1px solid rgba(217,183,109,.2);box-shadow:0 14px 30px rgba(0,0,0,.25)}
.merchant-bubble::before{content:"";position:absolute;top:-7px;left:50%;width:12px;height:12px;background:#142b21;border-left:1px solid rgba(217,183,109,.2);border-top:1px solid rgba(217,183,109,.2);transform:translateX(-50%) rotate(45deg)}
.merchant-bubble p{font-size:12px;line-height:1.5;color:var(--cream-dim);font-style:italic}
.merchant-bubble span{display:block;margin-top:8px;font-size:9px;letter-spacing:.12em;text-transform:uppercase;color:var(--gold);text-align:right}
.shop-gold{display:flex;align-items:center;gap:6px;margin-top:14px;padding:7px 13px;border-radius:999px;border:1px solid rgba(217,183,109,.25);background:rgba(6,17,13,.5);font-size:12px}
.shop-gold b{color:var(--gold-2);font-size:15px}.shop-gold span:last-child{font-size:9px;color:var(--muted);text-transform:uppercase;letter-spacing:.1em}
.shop-stock{min-width:0}
.shop-heading{display:flex;justify-content:space-between;align-items:flex-end;gap:12px;margin-bottom:18px}
.shop-heading h2{font-size:clamp(24px,2.4vw,34px);margin-top:5px}
.shop-section{margin-bottom:18px}
.shop-section-title{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid rgba(217,183,109,.14);padding-bottom:7px;margin-bottom:10px;font-size:10px;letter-spacing:.13em;text-transform:uppercase;color:var(--gold)}
.shop-sub{font-size:8px;letter-spacing:.06em;color:var(--muted-2);text-transform:none}
.shop-cards{display:flex;gap:10px;overflow-x:auto;padding:8px 4px 10px;min-height:196px}
.shop-cards .card{cursor:pointer}
.shop-cards .card:hover{transform:translateY(-8px)}
.shop-items{display:grid;grid-template-columns:repeat(auto-fill,minmax(155px,1fr));gap:8px}
.shop-item{display:flex;align-items:center;gap:9px;padding:9px 11px;border-radius:9px;border:1px solid rgba(255,255,255,.08);background:rgba(19,42,32,.6);text-align:left;transition:.18s;min-height:58px;min-width:0}
.shop-item:hover:not(.sold){background:rgba(31,65,49,.8);border-color:rgba(217,183,109,.26);transform:translateY(-1px)}
.shop-item.sold{opacity:.32;filter:grayscale(.8);pointer-events:none}
.shop-item-icon{width:34px;height:34px;border-radius:50%;display:flex;align-items:center;justify-content:center;background:rgba(0,0,0,.24);border:1px solid rgba(255,255,255,.08);font-size:16px;flex:0 0 auto}
.shop-item-copy{display:flex;flex-direction:column;line-height:1.2;min-width:0}
.shop-item-copy b{font-size:11px;color:var(--cream)}
.shop-item-copy span{font-size:8px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.shop-item-price{margin-left:auto;font-size:10px;color:var(--gold-2);white-space:nowrap;flex:0 0 auto}
.shop-services{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:4px}
.service-card{display:flex;align-items:center;gap:10px;padding:11px 13px;border-radius:9px;border:1px dashed rgba(217,183,109,.2);background:rgba(217,183,109,.04);text-align:left;transition:.18s}
.service-card:hover:not(:disabled){background:rgba(217,183,109,.09);border-color:rgba(217,183,109,.4)}
.service-card:disabled{opacity:.35}
.service-icon{font-size:17px;color:var(--gold);width:26px;text-align:center}
.service-card>span:nth-child(2){display:flex;flex-direction:column;line-height:1.2}
.service-card b{font-size:11px;color:var(--cream)}
.service-card small{font-size:8px;color:var(--muted)}
.service-price{margin-left:auto;font-size:10px;color:var(--gold-2);white-space:nowrap}

/* ============================================================
   Camp
